package com.ecobridge.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="collectors") public class Collector {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false,unique=true) private Long userId; @Column(nullable=false,length=20) private String phone; @Column(name="vehicle_type",length=100) private String vehicleType; @Column(name="vehicle_number",length=50) private String vehicleNumber; @Column(name="service_area",nullable=false,length=255) private String serviceArea; @Column(name="verification_status",nullable=false,length=30) private String verificationStatus="PENDING"; @Column(name="availability_status",nullable=false,length=30) private String availabilityStatus="OFFLINE"; @Column(nullable=false,precision=3,scale=2) private BigDecimal rating=BigDecimal.ZERO; @Column(name="total_completed_pickups",nullable=false) private int totalCompletedPickups; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 @PrePersist void create(){var n=Instant.now();createdAt=n;updatedAt=n;} @PreUpdate void update(){updatedAt=Instant.now();}
 public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public String getVehicleType(){return vehicleType;} public void setVehicleType(String v){vehicleType=v;} public String getVehicleNumber(){return vehicleNumber;} public void setVehicleNumber(String v){vehicleNumber=v;} public String getServiceArea(){return serviceArea;} public void setServiceArea(String v){serviceArea=v;} public String getVerificationStatus(){return verificationStatus;} public void setVerificationStatus(String v){verificationStatus=v;} public String getAvailabilityStatus(){return availabilityStatus;} public void setAvailabilityStatus(String v){availabilityStatus=v;} public BigDecimal getRating(){return rating;} public int getTotalCompletedPickups(){return totalCompletedPickups;} public void setTotalCompletedPickups(int v){totalCompletedPickups=v;}
}
